"""Lifecycle adversaries use the real ingress proxy; no successful fetch stubs."""
import pathlib,sys,unittest,json,copy,os
sys.path.insert(0,str(pathlib.Path(__file__).parent))
import test_design_browser as setup_module
from playwright.sync_api import expect
class DesignLifecycleTests(unittest.TestCase):
 setUp=setup_module.DesignBrowserTests.setUp
 tearDown=setup_module.DesignBrowserTests.tearDown
 def test_delayed_failed_outoforder_identity_and_cas(self):
  p=self.page;a=self.before;b=self.f.store.create('alice','Second dashboard');p.locator('[data-step="1"]').click();p.reload();p.locator('.draft-row').filter(has_text=b['name']).get_by_role('button',name='Öffnen',exact=True).click();self.proxy.hold_response=('GET','/api/dashboards/'+b['id']+'/design');p.locator('[data-step="3"]').click();self.assertTrue(self.proxy.response_arrived.wait(5));expect(p.locator('#design-save')).to_be_disabled();expect(p.locator('#design-output')).to_be_hidden();self.assertFalse(p.evaluate('()=>designSave()'));p.locator('[data-step="1"]').click();p.locator('.draft-row').filter(has_text=a['name']).get_by_role('button',name='Öffnen',exact=True).click();p.locator('[data-step="3"]').click();expect(p.locator('#design-output-title')).to_have_text(a['name']);p.locator('[data-design-profile="ivory"]').click();self.proxy.release_response.set();p.wait_for_timeout(200);expect(p.locator('#design-output')).to_have_attribute('data-profile','ivory');expect(p.locator('#design-dashboard')).to_have_text('Dashboard: '+a['name']);self.f.store.update('alice',a['id'],a['revision'],{'description':'Other writer'});p.locator('#design-save').click();expect(p.locator('#notice')).to_contain_text('inzwischen geändert');expect(p.locator('#design-output')).to_have_attribute('data-profile','ivory');p.locator('[data-step="1"]').click();p.locator('#dialog-discard').click();p.locator('.draft-row').filter(has_text=b['name']).get_by_role('button',name='Öffnen',exact=True).click();self.proxy.lost_read_path='/api/dashboards/'+b['id']+'/design';p.locator('[data-step="3"]').click();expect(p.locator('#notice')).to_contain_text('Verbindung unterbrochen');expect(p.locator('#design-save')).to_be_disabled();expect(p.locator('#design-output')).to_be_hidden();self.assertNotIn('design',self.f.store.get('alice',b['id']))
 def test_pending_inventory_from_previous_identity_does_not_delay_new_preview(self):
  p=self.page;b=self.f.store.create('alice','Inventory B');p.reload();p.locator('[data-step="3"]').click();expect(p.locator('#design-status')).to_contain_text('Frisch gelesen');self.proxy.hold_response=('GET','/api/ha/inventory');p.locator('#design-refresh').click();self.assertTrue(self.proxy.response_arrived.wait(5));p.locator('[data-step="1"]').click();p.locator('.draft-row').filter(has_text=b['name']).get_by_role('button',name='Öffnen',exact=True).click();p.locator('[data-step="3"]').click();expect(p.locator('#design-status')).to_contain_text('Frisch gelesen');self.proxy.release_response.set();expect(p.locator('#design-output-title')).to_have_text(b['name'])
 def test_save_busy_all_phases_and_uncertain_readback_no_retry(self):
  p=self.page;id=self.before['id'];expect(p.locator('#design-status')).to_contain_text('Frisch gelesen')
  for i,phase in enumerate([('POST','/api/dashboards/'+id+'/design'),('GET','/api/dashboards/'+id),('GET','/api/dashboards')]):
   p.locator('[data-design-profile="ivory"' +']' if i%2==0 else '[data-design-profile="noir"]').click();self.proxy.hold_response=phase;self.proxy.response_arrived.clear();self.proxy.release_response.clear();p.locator('#design-save').click();self.assertTrue(self.proxy.response_arrived.wait(5));expect(p.locator('#design-width')).to_be_disabled();expect(p.locator('#design-category')).to_be_disabled();expect(p.locator('#design-save')).to_be_disabled();p.keyboard.type('999');self.proxy.release_response.set();expect(p.locator('#design-save')).to_be_enabled();expect(p.locator('#design-dirty')).to_contain_text('Gespeichert')
  p.locator('[data-design-profile="noir"]').click();self.proxy.lose_read_after_post=('/api/dashboards/'+id+'/design','/api/dashboards/'+id);p.locator('#design-save').click();expect(p.locator('#notice')).to_contain_text('nicht eindeutig bestätigt');expect(p.locator('#design-dirty')).to_contain_text('Ungespeichert');count=sum(x[0]=='POST' for x in self.proxy.requests);p.locator('#design-save').click();expect(p.locator('#notice')).to_contain_text('unklar');self.assertEqual(count,sum(x[0]=='POST' for x in self.proxy.requests))
 def test_focused_override_survives_poll_staleness_and_registry_rename(self):
  p=self.page;expect(p.locator('#design-status')).to_contain_text('Frisch gelesen');p.locator('#design-customize summary').click();p.locator('#design-override-radius').fill('23');p.locator('#design-override-radius').focus();self.f.peer.data['states'][0]['state']='off';p.evaluate('()=>designRefresh()');expect(p.locator('[data-entity="registry:reg1"] .design-value')).to_have_text('off');expect(p.locator('#design-override-radius')).to_be_focused();expect(p.locator('#design-override-radius')).to_have_value('23');self.f.peer.fail='get_states';p.evaluate('()=>designRefresh()');expect(p.locator('#design-status')).to_contain_text('Veraltet');expect(p.locator('[data-entity="registry:reg1"] .design-quality')).to_contain_text('Veraltet');self.f.peer.fail=None;self.f.peer.data['entities'][0]['entity_id']='light.renamed';self.f.peer.data['states'][0]['entity_id']='light.renamed';p.evaluate('()=>designRefresh()');p.locator('[data-entity="registry:reg1"] details').evaluate('(e)=>e.open=true');expect(p.locator('[data-entity="registry:reg1"]')).to_contain_text('light.renamed');self.assertEqual(self.f.store.get('alice',self.before['id']),self.before)
 def test_new_browser_process_native_report_backnavigation_and_background(self):
  from test_images import png
  p=self.page;f=self.f;d=f.store.import_native('alice','Persistent native',{'views':[{'title':'Saved native','cards':[{'type':'entity','entity':'light.fixture'}]}]});img=f.store.put_image('alice','Synthetic image',png());settings=copy.deepcopy(d['settings']);settings['background'].update(imageId=img['id'],attachment='fixed',opacity=40);d=f.store.update('alice',d['id'],d['revision'],{'settings':settings});p.reload();p.locator('.draft-row').filter(has_text=d['name']).get_by_role('button',name='Öffnen',exact=True).click();p.locator('[data-step="3"]').click();expect(p.locator('#design-status')).to_contain_text('Frisch gelesen');p.locator('[data-design-profile="ivory"]').click();p.locator('#design-save').click();expect(p.locator('#design-dirty')).to_contain_text('Gespeichert');self.assertEqual(p.evaluate('()=>importReport.revision'),d['revision']+1);self.assertIn('/api/images/',p.locator('#design-image').evaluate('(e)=>getComputedStyle(e).backgroundImage'));self.assertGreater(p.locator('#design-image').bounding_box()['height'],100)
  self.b.close();self.b=self.p.chromium.launch(headless=True,args=['--no-sandbox']);self.ctx=self.b.new_context(extra_http_headers={'X-Remote-User-Id':'alice'});self.page=self.ctx.new_page();p=self.page;p.goto(self.proxy.url);p.locator('.draft-row').filter(has_text=d['name']).get_by_role('button',name='Öffnen',exact=True).click();p.locator('[data-step="3"]').click();expect(p.locator('#design-output')).to_have_attribute('data-profile','ivory');p.locator('#design-background-link').click();expect(p.locator('#bg-color')).to_be_visible();expect(p.locator('#image-choice')).to_have_value(img['id']);self.assertEqual(f.store.get('alice',d['id'])['native'],d['native'])
if __name__=='__main__':unittest.main()
